export function sampleImageFor(name: string): string | null {
  const slug = name.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return SAMPLE_PRODUCT_IMAGES.has(slug) ? '/img/products/' + slug + '.jpg' : null;
}
